-- ----------------------------
-- Table structure for tbl_flight
-- ----------------------------
DROP TABLE IF EXISTS `tbl_flight`;
CREATE TABLE `tbl_flight` (
  `id` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '主键',
  `plan_id` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '航班计划id',
  `uuid` bigint DEFAULT NULL COMMENT '外部数据id',
  `flight_no` varchar(7) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '航班号',
  `flight_date` date NOT NULL COMMENT '航班日期',
  `carrier` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '承运人',
  `plane_num` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '机号',
  `plane_type` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '机型',
  `dep` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '始发站',
  `dest` varchar(4) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '目的站',
  `dep_time` datetime DEFAULT NULL COMMENT '预计起飞',
  `dest_time` datetime DEFAULT NULL COMMENT '预计到达',
  `plan_dep_time` datetime DEFAULT NULL COMMENT '计划起飞',
  `plan_dest_time` datetime DEFAULT NULL COMMENT '计划到达',
  `act_dep_time` datetime DEFAULT NULL COMMENT '实际起飞时间',
  `act_dest_time` datetime DEFAULT NULL COMMENT '实际落地时间',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '航班状态1:正常,2:取消,3:延误,4:起飞,5:备降,6:到达,7:改航',
  `flight_quality` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '航班性质 J加班 N正班 B包机 D调机 X训练 S试飞 Z专机 T救灾 A补班 O公务 Y校验飞行 H滑飞机',
  `open_weight` decimal(10,2) DEFAULT NULL COMMENT '剩余可用开放重量',
  `open_volume` decimal(10,2) DEFAULT NULL COMMENT '剩余可用开放体积',
  `max_weight` decimal(10,2) DEFAULT NULL COMMENT '最大业载',
  `max_volume` decimal(10,2) DEFAULT NULL COMMENT '最大体积',
  `control_weight` decimal(10,2) DEFAULT NULL COMMENT '剩余可用控制重量',
  `control_volume` decimal(10,2) DEFAULT NULL COMMENT '剩余可用控制体积',
  `airline_icao` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '航空公司三字码',
  `manifest_close` datetime DEFAULT NULL COMMENT '舱单关闭时间',
  `is_delete` tinyint(1) NOT NULL COMMENT '是否删除 0:未删除,1:删除',
  `operate_by` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '操作人名称',
  `operate_id` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '操作人Id',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `create_by` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人名称',
  `dept_id` bigint DEFAULT NULL COMMENT '创建人部门ID',
  `ancestors` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '创建人部门祖级列表',
  `update_by` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '修改人名称',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  `open_or_close` tinyint(1) NOT NULL DEFAULT '1' COMMENT '开/关舱状态 0:关,1:开',
  `remark` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  `send_receipt` smallint DEFAULT NULL COMMENT '是否已经发送了海关回执，1是',
  `remind` smallint DEFAULT NULL COMMENT '是否已经发送了提醒，1是',
  KEY `id` (`id`) USING BTREE COMMENT '主键',
  KEY `flight_index` (`dep`,`dest`,`flight_no`,`flight_date`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='动态航班表';

